import React from 'react';
import { PDFDownloadLink } from '@react-pdf/renderer';
import PdfDocument from '../pdf/PdfDocument';
// Optional CSS import if you create a dedicated stylesheet
import './PdfDownloadButton.css';

function PdfDownloadButton({ army, equipment }) {
  return (
    <PDFDownloadLink
      className="pdf-download-link"
      document={<PdfDocument army={army} equipment={equipment} />}
      fileName="BloodOnSnow_ArmyRoster.pdf"
    >
      {({ loading }) => (loading ? 'Generating PDF...' : 'Download Army Roster PDF')}
    </PDFDownloadLink>
  );
}

export default PdfDownloadButton;
