// src/components/ArmyBuilder.jsx

import React, { useState, useEffect } from 'react';
import unitsData from '../data/units.json';
import equipmentData from '../data/equipment.json';

import UnitCard from './UnitCard';
import PdfDownloadButton from './PdfDownloadButton';
import './ArmyBuilder.css';

function ArmyBuilder() {
  const [units, setUnits] = useState([]);
  const [equipment, setEquipment] = useState([]);
  const [army, setArmy] = useState([]);
  const [selectedFaction, setSelectedFaction] = useState(null);
  const [showPdfLink, setShowPdfLink] = useState(false);

  // Night mode toggle
  const [nightMode, setNightMode] = useState(false);

  useEffect(() => {
    setUnits(unitsData);
    setEquipment(equipmentData);
  }, []);

  const addUnitToArmy = (unitId) => {
    const foundUnit = units.find((u) => u.id === unitId);
    if (!foundUnit) return;

    // Restrict to 1 Cossack
    if (foundUnit.name === 'Cossack') {
      const alreadyHasCossack = army.some((u) => u.name === 'Cossack');
      if (alreadyHasCossack) {
        alert('Only one Cossack allowed!');
        return;
      }
    }

    // If it's a cossack, automatically cavalry
    const newArmyUnit = {
      ...foundUnit,
      selectedEquipment: [],
      isCavalry: foundUnit.name === 'Cossack',
    };

    setArmy([...army, newArmyUnit]);
    setShowPdfLink(false);
  };

  const removeUnitFromArmy = (index) => {
    const updatedArmy = [...army];
    updatedArmy.splice(index, 1);
    setArmy(updatedArmy);
    setShowPdfLink(false);
  };

  const updateEquipmentSelection = (armyIndex, newSelectedEquipment) => {
    const updatedArmy = [...army];
    updatedArmy[armyIndex].selectedEquipment = newSelectedEquipment;
    setArmy(updatedArmy);
    setShowPdfLink(false);
  };

  /**
   * If toggled to cavalry, remove any disallowed gear (rifles, machine guns).
   */
  const updateCavalryStatus = (armyIndex, isCavalry) => {
    const updatedArmy = [...army];
    const unit = updatedArmy[armyIndex];

    unit.isCavalry = isCavalry;

    if (isCavalry) {
      // remove any rifles or machine guns
      unit.selectedEquipment = unit.selectedEquipment.filter((eqId) => {
        const eqItem = equipment.find((e) => e.id === eqId);
        if (!eqItem) return false;
        return !(eqItem.type === 'Rifles' || eqItem.type === 'Machine guns');
      });
    }

    setArmy(updatedArmy);
    setShowPdfLink(false);
  };

  const totalPoints = army.reduce((acc, unit) => {
    const eqPoints = (unit.selectedEquipment || []).reduce((sum, eqId) => {
      const eqItem = equipment.find((e) => e.id === eqId);
      return eqItem ? sum + eqItem.points : sum;
    }, 0);
    const cavalryCost = unit.isCavalry ? 7 : 0;
    return acc + (unit.basePoints || 0) + eqPoints + cavalryCost;
  }, 0);

  const filteredUnits = selectedFaction
    ? units.filter((u) => u.faction === selectedFaction)
    : [];

  return (
    <>
      {/* 
        We add "night-mode" to BODY as well, so the entire page background is dark. 
        We do this by toggling a class on the top-level <body> using a side-effect 
        OR by wrapping everything in a top-level div. 
        A simpler approach is to apply .night-mode to .army-builder 
        and also override the <body> background in the same CSS if you wish.
      */}
      <div className={nightMode ? 'night-mode-page' : ''}>
        {/* 
          The container for our builder: toggles .night-mode 
          so the content inside also changes color. 
        */}
        <div className={`army-builder ${nightMode ? 'night-mode' : ''}`}>
          {/* Night Mode Switch top-right */}
          <div className="theme-switch">
            <label>
              <input
                type="checkbox"
                checked={nightMode}
                onChange={(e) => setNightMode(e.target.checked)}
              />
              Night Mode
            </label>
          </div>

          <h1>Blood on Snow Army Builder</h1>

          <div className="faction-section">
            <h2>Select Faction</h2>
            <button
              className="faction-button"
              onClick={() => setSelectedFaction('Whites')}
              disabled={selectedFaction === 'Whites'}
            >
              Whites
            </button>
            <button
              className="faction-button"
              onClick={() => setSelectedFaction('Reds')}
              disabled={selectedFaction === 'Reds'}
            >
              Reds
            </button>
          </div>

          {selectedFaction && (
            <div className="add-units-section">
              <h2>Add Units ({selectedFaction})</h2>
              {filteredUnits.map((unit) => {
                const tooltip = buildUnitTooltip(unit);
                return (
                  <button
                    key={unit.id}
                    title={tooltip}
                    onClick={() => addUnitToArmy(unit.id)}
                    className="add-unit-button"
                  >
                    Add {unit.name}
                  </button>
                );
              })}
            </div>
          )}

          <div className="current-army">
            <h2>Current Army</h2>
            {army.length === 0 && <p>No units added yet.</p>}
            {army.map((armyUnit, index) => (
              <UnitCard
                key={`army-unit-${index}`}
                unit={armyUnit}
                equipment={equipment}
                onEquipmentChange={(newEq) => updateEquipmentSelection(index, newEq)}
                onCavalryChange={(isCav) => updateCavalryStatus(index, isCav)}
                onRemove={() => removeUnitFromArmy(index)}
              />
            ))}
          </div>

          {/* 
            Hide PDF link if army is empty or until user wants it.
            Or show it if user toggled it on. 
          */}
          {!showPdfLink && army.length > 0 && (
            <button className="generate-pdf" onClick={() => setShowPdfLink(true)}>
              Generate PDF
            </button>
          )}
          {showPdfLink && (
            <PdfDownloadButton army={army} equipment={equipment} />
          )}
        </div>

        {/* 
          This is a separate floating element to show total points at all times 
        */}
        <div className={`points-display ${nightMode ? 'night-points' : ''}`}>
          <span>Total Points: {totalPoints}</span>
        </div>
      </div>
    </>
  );
}

function buildUnitTooltip(unit) {
  const { basePoints, stats, traits } = unit;
  const statsStr = `MS:${stats.ms}, T:${stats.t}, D:${stats.d}, C:${stats.c}, E:${stats.e}`;
  return `Points: ${basePoints}, ${statsStr}, Trait: ${traits}`;
}

export default ArmyBuilder;
