// src/pdf/PdfDocument.jsx
import React from 'react';
import {
  Page,
  Text,
  View,
  Document,
  StyleSheet,
} from '@react-pdf/renderer';

// Example: if you have a logo, place it in your public folder or import it
// import logo from '../assets/logo.png'; // Or a local image

const styles = StyleSheet.create({
  page: {
    fontSize: 11,
    padding: 20,
    fontFamily: 'Helvetica',
    backgroundColor: '#ffffff',
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    borderBottom: '1 solid #ccc',
    marginBottom: 10,
    paddingBottom: 6,
  },
  headerLeft: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  headerTitle: {
    fontSize: 14,
    fontWeight: 'bold',
  },
  headerRight: {
    fontSize: 10,
    color: '#666',
  },
  unitContainer: {
    marginBottom: 10,
    padding: 10,
    border: '1 solid #ccc',
    borderRadius: 4,
  },
  unitTitle: {
    fontSize: 12,
    fontWeight: 'bold',
    marginBottom: 4,
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  unitStats: {
    marginBottom: 4,
  },
  equipmentSection: {
    marginTop: 4,
  },
  equipmentItem: {
    marginLeft: 8,
    marginBottom: 2,
  },
  traitText: {
    fontStyle: 'italic',
    fontSize: 10,
    marginLeft: 14,
  },
  // Example two-column layout for units
  twoColumnLayout: {
    flexDirection: 'row',
    flexWrap: 'wrap', // allows them to wrap to next line
    justifyContent: 'space-between',
  },
  unitBlock: {
    width: '48%', // about half width
    marginBottom: 10,
  },
});

const PdfDocument = ({ army, equipment }) => {
  // Helper to find equipment details by ID
  const getEquipmentById = (id) => equipment.find((eq) => eq.id === id);

  return (
    <Document>
      <Page size="A4" style={styles.page}>
        {/* --- Header --- */}
        <View style={styles.header}>
          <View style={styles.headerLeft}>
            {/* Example Logo - comment out if you don't have a logo 
            <Image src={logo} style={{ width: 40, height: 40, marginRight: 8 }} />
            */}
            <Text style={styles.headerTitle}>Blood on Snow - Army Roster</Text>
          </View>
          <Text style={styles.headerRight}>Generated PDF</Text>
        </View>

        {/* Example: If you want a sub-header or notes: 
        <Text style={{ marginBottom: 10, fontSize: 10, color: '#555' }}>
          Here is your current army list for the upcoming game. 
          Make sure to verify points and equipment restrictions before playing!
        </Text> 
        */}

        {/* --- Two Column Layout for Units --- */}
        <View style={styles.twoColumnLayout}>
          {army.map((unit, idx) => {
            const { name, basePoints, stats, traits, selectedEquipment, isCavalry } =
              unit;
            const eqItems = (selectedEquipment || []).map((eqId) => getEquipmentById(eqId));
            const displayMs = isCavalry ? 16 : stats.ms;

            return (
              <View key={idx} style={styles.unitBlock}>
                <View style={styles.unitContainer}>
                  <View style={styles.unitTitle}>
                    <Text>
                      {name} ({basePoints} pts {isCavalry ? '+7 Cav' : ''})
                    </Text>
                  </View>
                  <Text style={styles.unitStats}>
                    <Text>
                      Stats: MS {displayMs}, T {stats.t}, D {stats.d}, C {stats.c}, E {stats.e}
                    </Text>
                  </Text>
                  <Text style={{ marginBottom: 4 }}>
                    Traits: {traits}
                  </Text>

                  <View style={styles.equipmentSection}>
                    <Text style={{ fontWeight: 'bold', marginBottom: 2 }}>
                      Equipment:
                    </Text>
                    {eqItems.length > 0 ? (
                      eqItems.map((eq, eqIdx) => {
                        if (!eq) {
                          return (
                            <Text key={`missing-${eqIdx}`} style={styles.equipmentItem}>
                              [Equipment not found]
                            </Text>
                          );
                        }
                        const { name: eqName, points, type, trait, stats: eqStats } = eq;
                        return (
                          <View key={eq.id} style={{ marginBottom: 2 }}>
                            <Text style={styles.equipmentItem}>
                              - {eqName} ({points} pts) - {type}
                            </Text>
                            {eqStats && (
                              <View style={{ marginLeft: 14 }}>
                                {eqStats.rof && <Text>ROF: {eqStats.rof} {'\n'}</Text>}
                                {eqStats.range && <Text>Range: {eqStats.range} {'\n'}</Text>}
                                {eqStats.capacity && <Text>Capacity: {eqStats.capacity} {'\n'}</Text>}
                                {eqStats.reliability && (
                                  <Text>Reliability: {eqStats.reliability} {'\n'}</Text>
                                )}
                              </View>
                            )}
                            {trait && <Text style={styles.traitText}>Trait: {trait}</Text>}
                          </View>
                        );
                      })
                    ) : (
                      <Text style={styles.equipmentItem}>No equipment selected</Text>
                    )}
                  </View>
                </View>
              </View>
            );
          })}
        </View>
      </Page>
    </Document>
  );
};

export default PdfDocument;
