// src/components/UnitCard.jsx
import React from 'react';
import EquipmentSelector from './EquipmentSelector';
import './UnitCard.css';

function UnitCard({ unit, equipment, onEquipmentChange, onCavalryChange, onRemove }) {
  const { name, basePoints, stats, traits, selectedEquipment, isCavalry } = unit;
  const displayMs = isCavalry ? 16 : stats.ms;

  return (
    <div className="unit-card">
      {/* Top-right remove button */}
      <button className="remove-unit-button-top" onClick={onRemove}>
        Remove Unit
      </button>

      <h4 className="unit-title">
        {name} ({basePoints} pts)
      </h4>
      <p className="unit-stats">
        <strong>Stats:</strong> MS: {displayMs}, T: {stats.t}, D: {stats.d}, C: {stats.c}, E: {stats.e}
      </p>
      <p className="unit-traits">
        <strong>Traits:</strong> {traits}
      </p>

      {/* Only show the "Horse (Cavalry)" checkbox if this unit is NOT a Cossack */}
      {name !== 'Cossack' && (
        <label className="cavalry-toggle">
          <input
            type="checkbox"
            checked={isCavalry}
            onChange={(e) => onCavalryChange(e.target.checked)}
          />
          Horse (Cavalry, +7 pts, MS=16)
        </label>
      )}

      <EquipmentSelector
        unit={unit}
        allEquipment={equipment}
        selectedEquipmentIds={selectedEquipment}
        onChange={onEquipmentChange}
      />

      {/* Original remove button at the bottom */}
      <button className="remove-unit-button" onClick={onRemove}>
        Remove Unit
      </button>
    </div>
  );
}

export default UnitCard;
