// src/components/EquipmentSelector.jsx

import React from 'react';
// Import the new CSS file
import './EquipmentSelector.css';

function EquipmentSelector({ unit, allEquipment, selectedEquipmentIds, onChange }) {
  const { isCavalry, name: unitName } = unit;

  const handleToggleEquipment = (eqId) => {
    if (selectedEquipmentIds.includes(eqId)) {
      onChange(selectedEquipmentIds.filter((id) => id !== eqId));
    } else {
      onChange([...selectedEquipmentIds, eqId]);
    }
  };

  return (
    <div className="equipment-selector">
      <h5 className="equipment-title">Equipment</h5>
      {allEquipment.map((eq) => {
        // 1. Disallow rifles & machine guns for cavalry
        if (isCavalry && (eq.type === 'Rifles' || eq.type === 'Machine guns')) {
          return null;
        }

        // 2. Disallow "Cossack" type if the unit is not a Cossack
        if (eq.type === 'Cossack' && unitName !== 'Cossack') {
          return null;
        }

        const isSelected = selectedEquipmentIds.includes(eq.id);
        const eqStats = eq.stats || {};

        return (
          <div key={eq.id} className="equipment-item">
            <label className="equipment-label">
              <input
                type="checkbox"
                checked={isSelected}
                onChange={() => handleToggleEquipment(eq.id)}
              />
              <span>
                {eq.name} (Cost: {eq.points}) - {eq.type}
              </span>
            </label>

            {/* Show stat fields if they exist */}
            {(eqStats.rof || eqStats.range || eqStats.capacity || eqStats.reliability) && (
              <ul className="equipment-stats">
                {eqStats.rof && <li>ROF: {eqStats.rof}</li>}
                {eqStats.range && <li>Range: {eqStats.range}</li>}
                {eqStats.capacity && <li>Capacity: {eqStats.capacity}</li>}
                {eqStats.reliability && <li>Reliability: {eqStats.reliability}</li>}
              </ul>
            )}

            {eq.trait && (
              <div className="equipment-trait">
                Trait: {eq.trait}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

export default EquipmentSelector;
